import java.util.ArrayDeque;
import java.util.Scanner;

public class E {
    static long[] bases = new long[100];
    static long[] pref;
    static int n;
    static long w, m;

    static class State {
        int pos;
        long rem;
        State(int pos, long rem) {
            this.pos = pos;
            this.rem = rem;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        w = sc.nextInt();
        m = sc.nextInt();
        if (w <= 3) {
            System.out.println("YES");
            return;
        }
        if (m < 0) {
            System.out.println("NO");
            return;
        }
        n = 0;
        for (long v = 1; v <= 2_000_000_000L; v *= w) {
            bases[n++] = v;
        }
        pref = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += bases[i];
            pref[i] = sum;
        }

        boolean found = false;
        ArrayDeque<State> stack = new ArrayDeque<>();
        stack.push(new State(n - 1, m));
        while (!stack.isEmpty()) {
            State s = stack.pop();
            int pos = s.pos;
            long rem = s.rem;
            if (pos < 0) {
                if (rem == 0) {
                    found = true;
                    break;
                }
                continue;
            }
            if (Math.abs(rem) > pref[pos]) continue;
            long b = bases[pos];
            stack.push(new State(pos - 1, rem - b));
            stack.push(new State(pos - 1, rem));
            stack.push(new State(pos - 1, rem + b));
        }
        System.out.println(found ? "YES" : "NO");
    }
}
